def is_balanced(text: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in text:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or mapping[char] != stack.pop():
                return False

    return not stack
```

